{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE eggozdb.maplemonk.postgre_total_customer_society AS SELECT u.id AS user_id, u.name, u.phone_number, DATE(u.created_at) AS signup_date, fo.first_order_date, fw.wallet_recharge_date, a.society_id, COALESCE(s.society_name, \'No Address\') AS society_name FROM postgres_users u LEFT JOIN (SELECT user_id, MIN(delivered_at) AS first_order_date FROM postgres_orders WHERE delivered_at IS NOT NULL GROUP BY user_id) fo ON fo.user_id = u.id LEFT JOIN (SELECT user_id, MIN(created_at) AS wallet_recharge_date FROM postgres_wallet GROUP BY user_id) fw ON fw.user_id = u.id LEFT JOIN (SELECT user_id, society_id FROM postgres_address QUALIFY ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY is_default DESC, modified_at DESC) = 1) a ON a.user_id = u.id LEFT JOIN postgres_society s ON s.id = a.society_id WHERE u.is_deleted = FALSE; CREATE OR REPLACE TABLE eggozdb.maplemonk.postgre_total_customer AS SELECT u.id as user_id, u.name, u.phone_number, date(u.created_at) as login_date, MIN(o.delivered_at) AS first_order_date, MIN(w.created_at) AS wallet_recharge_date FROM postgres_users u LEFT JOIN postgres_orders o ON u.id = o.user_id LEFT JOIN postgres_wallet w ON u.id = w.user_id WHERE u.is_deleted = FALSE GROUP BY u.id, u.name, u.phone_number, u.created_at; Create or replace table eggozdb.maplemonk.postgre_app_data_overall as SELECT date(COALESCE(o.delivered_at, o.created_at)) AS date, u.id AS user_id, o.id AS order_id, u.name AS name_customer, u.phone_number, p.sku_count, p.short_name, oi.quantity, o.payable_amount, w.id AS wallet_id, w.available_balance, w.total_added_balance, w.total_utilized_balance, w.total_refunded_balance, w.total_bonus_balance, w.created_at AS wallet_recharge_date FROM postgres_order_item oi JOIN postgres_product_city_price pcp ON pcp.id = oi.product_city_id JOIN postgres_product p ON p.id = pcp.product_id JOIN postgres_orders o ON o.id = oi.order_id JOIN postgres_users u ON u.id = o.user_id LEFT JOIN postgres_wallet w ON w.user_id = u.id ORDER BY 1; CREATE OR REPLACE TABLE eggozdb.maplemonk.postgre_app_scoiety_data AS SELECT DATE(COALESCE(o.delivered_at, o.created_at)) AS date, o.user_id, o.id AS order_id, o.payable_amount, COALESCE(s.society_name, \'No Society\') AS society_name, p.short_name, DATE(w.created_at) AS wallet_recharge_date, s.id AS society_id, oi.quantity, IFF(ROW_NUMBER() OVER (PARTITION BY o.id ORDER BY oi.id) = 1, 1, 0) AS is_first_item_of_order FROM postgres_orders o LEFT JOIN postgres_address a ON a.id = o.address_id LEFT JOIN postgres_society s ON s.id = a.society_id LEFT JOIN (SELECT user_id, MIN(created_at) AS created_at FROM postgres_wallet GROUP BY user_id) w ON w.user_id = o.user_id LEFT JOIN postgres_order_item oi ON oi.order_id = o.id LEFT JOIN postgres_product_city_price pcp ON pcp.id = oi.product_city_id LEFT JOIN postgres_product p ON p.id = pcp.product_id; CREATE OR REPLACE TABLE eggozdb.maplemonk.postgre_total_customer1 AS SELECT u.id AS user_id, u.name, u.phone_number, DATE(u.created_at) AS signup_date, fo.first_order_date, fw.wallet_recharge_date FROM postgres_users u LEFT JOIN ( SELECT user_id, MIN(delivered_at) AS first_order_date FROM postgres_orders WHERE delivered_at IS NOT NULL GROUP BY user_id ) fo ON fo.user_id = u.id LEFT JOIN ( SELECT user_id, MIN(created_at) AS wallet_recharge_date FROM postgres_wallet GROUP BY user_id ) fw ON fw.user_id = u.id WHERE u.is_deleted = FALSE; CREATE OR REPLACE TABLE eggozdb.maplemonk.Raw_repeated_Ordered AS SELECT DATE(o.delivered_at) AS date, u.id AS user_id, o.id AS order_id, u.name, u.phone_number, u.email, p.sku_count, p.short_name, SUM(oi.quantity) AS quantity, o.payable_amount AS payable_amount FROM postgres_orders o JOIN postgres_users u ON o.user_id = u.id JOIN postgres_order_item oi ON oi.order_id = o.id JOIN postgres_product_city_price pcp ON pcp.id = oi.product_city_id JOIN postgres_product p ON p.id = pcp.product_id JOIN postgres_retailer r ON r.id = o.retailer_id GROUP BY DATE(o.delivered_at), u.id, o.id, u.name, u.phone_number, u.email, p.sku_count, p.short_name, o.payable_amount;",
